  const $ = (s) => [...document.querySelectorAll(s)];
  const text = (el,value) => { if(el) el.textContent=value; };
  const html = (el,value) => { if(el) el.innerHTML=value; };
  const label = (el,value) => { if(!el)return; const node=[...el.childNodes].find(n=>n.nodeType===Node.TEXT_NODE&&n.textContent.trim()); if(node)node.textContent=`${value} `; else el.prepend(document.createTextNode(value)); };
  const format = (value,vars={}) => String(value??'').replace(/\{(\w+)\}/g,(_,k)=>vars[k]??'');
  let locale='en';
  const get = (key) => key.split('.').reduce((value,part)=>value?.[part],M[locale]) ?? key.split('.').reduce((value,part)=>value?.[part],M.en) ?? '';
  const apply = (next) => {
    locale=supported.includes(next)?next:'en';
    const htmlLang=locale==='zh-CN'?'zh-CN':locale;
    document.documentElement.lang=htmlLang;
    document.documentElement.dir=locale==='ar'?'rtl':'ltr';
    const data=M[locale];
    for(const [key,selector,mode] of B){
      const value=data[key]; if(value===undefined)continue;
      const nodes=$(selector);
      if(mode==='list'||mode==='labelList'||mode==='radioGroups'||mode==='panelStates'){
        if(mode==='radioGroups'){
          const inputs=[...document.querySelectorAll('.radio-option input')];
          const byGroup={addressLevel:0,careerLevel:1,academicLevel:2,projectLevel:3,certificationLevel:4,documentLevel:5};
          for(const input of inputs){const group=byGroup[input.name];const index=[...input.closest('.radio-list').querySelectorAll('input')].indexOf(input);const v=value[group]?.[index];if(v!==undefined)label(input.closest('.radio-option'),v);}
        } else nodes.forEach((el,i)=>{const v=Array.isArray(value)?(value[i]??value[value.length-1]):value;if(v===undefined)return;if(mode==='labelList')label(el,v);else if(mode==='panelStates')text(el,el.closest('[data-category]')?.dataset.category==='certifications'?data.panelStates[2]:data.panelStates[0]);else text(el,v);});
      } else if(mode==='html') html(nodes[0],value);
      else if(mode==='plainHtml'){
        // Keep the REAL owner's H1 immutable. The legacy translated slogan
        // originally targeted .hero h1, overwriting the personal name.
        // Decode the trusted translation markup as text in the role subtitle.
        const phrase=document.createElement('span');
        phrase.innerHTML=String(value).replace(/<br\s*\/?>/gi,' ');
        text(nodes[0],(phrase.textContent||'').replace(/\s+/g,' ').trim());
      }
      else if(mode==='label') label(nodes[0],value);
      else text(nodes[0],value);
    }
    const optionValues=data.theme; document.querySelectorAll('#theme-select option').forEach((o,i)=>{ if(optionValues[i]!==undefined)text(o,optionValues[i]); });
    const navLinks=$('#navlinks a[href^="#"]'); navLinks.forEach((a,i)=>{if(data.nav[i]!==undefined)label(a,data.nav[i]);});
    const ticker=$('.ticker-group > span'); ticker.forEach((el,i)=>{const v=data.ticker[i%data.ticker.length];label(el,v);});
    // Keep the two repeated groups identical in every language, including RTL.
    const tickerDescription=document.querySelector('.ticker-screenreader');
    if(tickerDescription)tickerDescription.textContent=data.ticker.join(' · ');
    const stats=[1000,20,200]; $('.proof strong').forEach((el,i)=>{el.textContent=`${new Intl.NumberFormat(locale).format(stats[i])}+`;});
    document.title=locale==='en'?'Professional portfolio':`Sudip Das · ${data.nav[0]||'Portfolio'}`;
    const meta=document.querySelector('meta[name="description"]'); if(meta)meta.content=data.heroCopy;
    const setAttr=(selector,name,value)=>{const el=document.querySelector(selector);if(el)el.setAttribute(name,value);};
    setAttr('.nav','aria-label',data.aria.navigation);setAttr('#language-select','aria-label',data.aria.language);setAttr('#theme-select','aria-label',data.aria.theme);setAttr('.hero-art','aria-label',data.aria.portrait);setAttr('.core img','alt',data.aria.portraitImage);setAttr('.ticker','aria-label',data.aria.ticker);setAttr('.request-progress','aria-label',data.aria.progress);
    const languageSelect=document.querySelector('#language-select');if(languageSelect)languageSelect.value=locale;
    document.dispatchEvent(new CustomEvent('profile-language-change',{detail:{locale}}));
    try{localStorage.setItem('sudip-profile-language',locale)}catch{}
  };
  const languageSelect=document.querySelector('#language-select');
  let initial='en';
  try{const saved=localStorage.getItem('sudip-profile-language');if(saved&&supported.includes(saved))initial=saved;else{const browser=(navigator.languages||[navigator.language||'en']).map(x=>x.toLowerCase());const match=supported.find(code=>browser.some(lang=>lang===code.toLowerCase()||lang.startsWith(code.split('-')[0].toLowerCase())));if(match)initial=match;}}catch{}
  apply(initial);
  languageSelect?.addEventListener('change',()=>apply(languageSelect.value));
